/// Sync modes.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum SyncMode {
    /// Sync is not running.
    NotRunning,
    /// Sync is held in a paused state and the wallet guard is dropped.
    Paused,
    /// Sync is running.
    Running,
    /// Sync is shutting down.
    Shutdown,
}

impl SyncMode {
    /// Returns the mode a completed scan leaves behind, which is `Shutdown` for a running engine and the same mode for every other.
    pub fn on_completion(self) -> Self {
        match self {
            Self::Running => Self::Shutdown,
            other => other,
        }
    }
}

/// The sync mode shared between the sync engine and the consumer that launched it.
///
/// Every clone reads and writes the one mode. A write that changes the mode notifies every receiver of
/// [`Self::subscribe`].
#[derive(Clone, Debug)]
pub struct SyncModeHandle(watch::Sender<SyncMode>);

impl Default for SyncModeHandle {
    fn default() -> Self {
        Self::new(SyncMode::NotRunning)
    }
}

impl SyncModeHandle {
    /// Creates a handle holding `mode`.
    pub fn new(mode: SyncMode) -> Self {
        Self(watch::Sender::new(mode))
    }

    /// Returns the mode held.
    pub fn get(&self) -> SyncMode {
        *self.0.borrow()
    }

    /// Replaces the mode held with `mode` and returns the mode it replaced.
    pub fn set(&self, mode: SyncMode) -> SyncMode {
        self.apply(|_replaced| mode)
    }

    /// Replaces the mode held with `step` of it in one exchange and returns the mode it replaced.
    pub fn apply(&self, step: impl FnOnce(SyncMode) -> SyncMode) -> SyncMode {
        let mut replaced = SyncMode::NotRunning;
        self.0.send_if_modified(|mode| {
            replaced = *mode;
            *mode = step(replaced);
            *mode != replaced
        });
        replaced
    }

    /// Moves the mode from `from` to `to` when it holds `from` and returns the mode it held before.
    pub fn transition(&self, from: SyncMode, to: SyncMode) -> SyncMode {
        self.apply(|mode| if mode == from { to } else { mode })
    }

    /// Returns a receiver whose [`watch::Receiver::changed`] resolves on the next change of mode after this call.
    pub fn subscribe(&self) -> watch::Receiver<SyncMode> {
        self.0.subscribe()
    }
}

pub(crate) async fn wallet_block_from_compact_block(
    consensus_parameters: &impl consensus::Parameters,
    fetch_request_sender: mpsc::UnboundedSender<FetchRequest>,
    block: &protocol::CompactBlock,
) -> Result<WalletBlock, ServerError> {
    let tree_bounds =
        calculate_block_tree_bounds(consensus_parameters, fetch_request_sender, block).await?;

    Ok(WalletBlock::from_parts(WalletBlockParts {
        block_height: block::get_compact_height(block),
        block_hash: block::get_compact_hash(block),
        prev_hash: block::get_compact_prev_hash(block),
        time: block.time,
        txids: block
            .vtx
            .iter()
            .map(transaction::get_compact_txid)
            .collect(),
        tree_bounds,
    }))
}

/// Reduces the wallet to what a build that never tracked `pool` would have
/// left behind: the very same scanned ranges, and none of that pool's data.
///
/// This is the state a wallet reaches by syncing across a pool's activation
/// on a build that predates the pool, which is not otherwise constructible
/// from outside. Scan-range priorities are deliberately untouched, since the
/// defect being reproduced is precisely that the ranges still claim to be
/// scanned.
#[cfg(any(test, feature = "test-features"))]
pub fn strip_pool_tracking_for_test<W>(wallet: &mut W, pool: ShieldedPool) -> Result<(), W::Error>
where
    W: traits::SyncWallet
        + traits::SyncBlocks
        + traits::SyncTransactions
        + traits::SyncNullifiers
        + traits::SyncShardTrees,
{
    for block in wallet.get_wallet_blocks_mut()?.values_mut() {
        block.clear_pool_tree_bounds_for_test(pool);
    }
    for transaction in wallet.get_wallet_transactions_mut()?.values_mut() {
        transaction.clear_pool_notes_for_test(pool);
    }

    let nullifiers = wallet.get_nullifiers_mut()?;
    match pool {
        ShieldedPool::Sapling => nullifiers.sapling.clear(),
        ShieldedPool::Orchard => nullifiers.orchard.clear(),
        ShieldedPool::Ironwood => nullifiers.ironwood.clear(),
    }

    let empty = ShardTrees::new();
    let shard_trees = wallet.get_shard_trees_mut()?;
    match pool {
        ShieldedPool::Sapling => shard_trees.sapling = empty.sapling,
        ShieldedPool::Orchard => shard_trees.orchard = empty.orchard,
        ShieldedPool::Ironwood => shard_trees.ironwood = empty.ironwood,
    }

    wallet.get_sync_state_mut()?.clear_shard_ranges(pool);

    Ok(())
}

pub(crate) trait SyncDomain {
    const SHIELDED_PROTOCOL: ShieldedPool;

    type Note: NoteInterface;
    type ShardStore: ShardStore<CheckpointId = BlockHeight>;

    fn notes_mut(wallet_transaction: &mut TransactionRecord) -> Vec<&mut Self::Note>;
}

impl SyncDomain for Sapling {
    const SHIELDED_PROTOCOL: ShieldedPool = ShieldedPool::Sapling;

    type Note = SaplingNote;
    type ShardStore = SaplingShardStore;

    fn notes_mut(wallet_transaction: &mut TransactionRecord) -> Vec<&mut Self::Note> {
        wallet_transaction.sapling_notes_mut()
    }
}

impl SyncDomain for Orchard {
    const SHIELDED_PROTOCOL: ShieldedPool = ShieldedPool::Orchard;

    type Note = OrchardNote;
    type ShardStore = OrchardShardStore;

    fn notes_mut(wallet_transaction: &mut TransactionRecord) -> Vec<&mut Self::Note> {
        wallet_transaction.orchard_notes_mut()
    }
}

impl SyncDomain for Ironwood {
    const SHIELDED_PROTOCOL: ShieldedPool = ShieldedPool::Ironwood;

    type Note = IronwoodNote;
    // Ironwood reuses the Orchard note commitment tree hash, so the same
    // store type serves its (separate) tree.
    type ShardStore = OrchardShardStore;

    fn notes_mut(wallet_transaction: &mut TransactionRecord) -> Vec<&mut Self::Note> {
        wallet_transaction.ironwood_notes_mut()
    }
}
